package com.enterprisecloud.iam.controller;

import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.session.FindByIndexNameSessionRepository;
import org.springframework.session.Session;
import org.springframework.web.bind.annotation.*;
import java.util.Map;

@RestController
@RequestMapping("/api/iam/sessions")
public class SessionTokenInspectController {

    private final FindByIndexNameSessionRepository<? extends Session> sessionRepository;

    public SessionTokenInspectController(FindByIndexNameSessionRepository<? extends Session> sessionRepository) {
        this.sessionRepository = sessionRepository;
    }

    @GetMapping("/{sessionId}/token-store")
    public ResponseEntity<Map<String, Object>> getSessionTokenStore(
            @PathVariable String sessionId,
            Authentication authentication) {
        Session session = sessionRepository.findById(sessionId);
        if (session == null) {
            return ResponseEntity.notFound().build();
        }
        String principalName = session.getAttribute(FindByIndexNameSessionRepository.PRINCIPAL_NAME_INDEX_NAME);
        if (principalName == null || !principalName.equals(authentication.getName())) {
            throw new AccessDeniedException("Authenticated user is not the owner of the requested session token store");
        }
        Map<String, Object> tokenAttributes = session.getAttribute("OAUTH2_CLIENT_TOKENS");
        return ResponseEntity.ok(tokenAttributes);
    }
}
